public class AutofillDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "Autofill",
            "Use autofill",
            ...
            Category.USABILITY, 5, Severity.WARNING,
            new Implementation(AutofillDetector.class, Scope.RESOURCE_FILE_SCOPE));
    private static final int AUTOFILL_MIN_SDK = 26;

    @Override public Collection<String> getApplicableElements() { return ALL; }

    @Override public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (context.getResourceFolderType() != ResourceFolderType.LAYOUT) return;
        if (context.getProject().getTargetSdk() < AUTOFILL_MIN_SDK) return;
        if (!isAutofillable(element)) return;
        if (element.hasAttributeNS(ANDROID_URI, ATTR_AUTOFILL_HINTS)) return;
        if (isNotImportantForAutofill(element)) return;
        context.report(ISSUE, element, context.getNameLocation(element), "...");
    }

    private static boolean isAutofillable(@NonNull Element element) {
        String tag = element.getTagName();
        if (tag.endsWith("EditText") || tag.endsWith("AutoCompleteTextView")
                || tag.endsWith("ExtractEditText") || tag.endsWith("SearchAutoComplete")) {
            return true;
        }
        return element.hasAttributeNS(ANDROID_URI, ATTR_INPUT_TYPE);
    }

    private static boolean isNotImportantForAutofill(@NonNull Element element) {
        Node curr = element;
        while (curr != null && curr.getNodeType() == Node.ELEMENT_NODE) {
            Element el = (Element) curr;
            String value = el.getAttributeNS(ANDROID_URI, ATTR_IMPORTANT_FOR_AUTOFILL);
            if (!value.isEmpty()) {
                if (value.equals("no") || value.equals("noExcludeDescendants")) {
                    return true;
                } else if (value.equals("yes") || value.equals("yesExcludeDescendants")
                        || value.equals("auto")) {
                    // explicit autofill choice; if it's yes or auto with no hints, report.
                    return false;
                }
                // could be numeric
                int important = -1;
                try { important = Integer.parseInt(value); } catch ...
                if (important == View.IMPORTANT_FOR_AUTOFILL_NO
                        || important == View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS) {
                    return true;
                }
            }
            curr = curr.getParentNode();
        }
        return false;
    }
}
```

